const items = $input.all();
if (!items.length || !items[0].json || !items[0].json.id) {
  return [];
}

const order = items[0].json;
const shipping = typeof order.shippingAddress === 'string' ? JSON.parse(order.shippingAddress) : (order.shippingAddress || {});
const orderItems = typeof order.items === 'string' ? JSON.parse(order.items) : (order.items || []);

const PAYMENT_METHODS = {
  PAGO_MOVIL: 'Pago Móvil',
  TRANSFERENCIA_BANCARIA: 'Transferencia Bancaria',
  EFECTIVO_USD: 'Efectivo en Divisas',
  ZELLE: 'Zelle',
  BINANCE_PAY: 'Binance Pay'
};

const POT_SIZE_LABELS = {
  POTE_4_PULGADAS: '4"',
  POTE_5_PULGADAS: '5"',
  POTE_6_PULGADAS: '6"',
  POTE_8_PULGADAS: '8"',
  CEBOLLERO: 'Cebollero',
  MINI: 'Mini',
  CANASTA: 'Canasta',
  TRONCO: 'Montada en Tronco'
};

const customerName = shipping.name || 'Cliente';
const customerId = shipping.idNumber || 'Sin Cédula/RIF';
const customerPhone = shipping.phone || 'Sin Teléfono';
const deliveryType = shipping.deliveryType === 'PICKUP' ? 'Retiro en Vivero' : 'Envío Nacional (MRW/Tealca)';
const city = shipping.city && shipping.state ? `${shipping.city}, ${shipping.state}` : (shipping.city || shipping.state || 'N/A');

let productsBlock = '';
orderItems.forEach((it) => {
  const sizeLabel = POT_SIZE_LABELS[it.size] || it.size || 'Estándar';
  const qtyStr = it.quantity > 1 ? `(x${it.quantity})` : '(x1)';
  const itemTotal = ((it.unitPrice || 0) * (it.quantity || 1)).toFixed(2);
  productsBlock += `• <b>${it.speciesName}</b>\n`;
  productsBlock += `  Tamaño: ${sizeLabel} ${qtyStr}\n`;
  productsBlock += `  Precio: $${itemTotal} USD\n`;
});

const subtotalUsd = Number(order.subtotal || 0).toFixed(2);
const totalUsd = Number(order.totalUsd || 0).toFixed(2);
const totalVes = Number(order.totalVes || 0).toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const rateStr = Number(order.exchangeRate || 0).toFixed(2);
const paymentMethodStr = PAYMENT_METHODS[order.paymentMethod] || order.paymentMethod;

let replyText = `\u200B\n<b>Nueva Orden de Venta</b>\n\n`;
replyText += `Orden: <b>${order.orderNumber}</b>\n`;
replyText += `Estado: Esperando Pago\n`;
replyText += `Método: ${paymentMethodStr}\n\n`;

replyText += `<b>Cliente:</b> ${customerName}\n`;
replyText += `Cédula/RIF: ${customerId}\n`;
replyText += `Teléfono: ${customerPhone}\n`;
replyText += `Modalidad: ${deliveryType}\n`;
replyText += `Ubicación: ${city}\n\n`;

replyText += `<b>Productos:</b>\n${productsBlock}\n`;

replyText += `Subtotal: $${subtotalUsd}\n`;
replyText += `<b>Total USD: $${totalUsd}</b>\n`;
replyText += `<b>Total VES: Bs. ${totalVes}</b>\n`;
replyText += `Tasa BCV: Bs. ${rateStr} / USD\n\n`;
replyText += `Reserva activa por 12 horas.`;

const rows = [
  {
    row: {
      buttons: [
        {
          text: '📋 Ver Orden en Panel',
          url: 'https://pristinoplant.com/admin/orders'
        }
      ]
    }
  }
];

return [{
  json: {
    orderId: order.id,
    orderNumber: order.orderNumber,
    replyText,
    keyboardRows: rows
  }
}];
